DO $exp$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Farmacoterapia de la Insuficiencia Cardíaca$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Farmacoterapia de la Insuficiencia Cardíaca$t$;
    RETURN;
  END IF;

  -- 01. Introducción al curso: farmacoterapia de la insuficiencia cardíaca en Colombia y guías vigentes a 2026
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La disnea que vuelve cada mes","texto":"Don Jaime tiene 70 años, vive en Barranquilla y ha ingresado tres veces en seis meses por falta de aire y edema. Toma furosemida, pero no recibe la terapia fundamental para la insuficiencia cardíaca con fracción de eyección reducida. Cada reingreso es una oportunidad perdida para iniciar o titular los fármacos que cambian el pronóstico. El Químico Farmacéutico puede detectar esa brecha y actuar."},"objetivos":["Describir el impacto de la insuficiencia cardíaca en Colombia.","Reconocer el papel del Químico Farmacéutico en la optimización del tratamiento.","Identificar las guías vigentes y los cuatro pilares de la IC con FEVI reducida.","Ubicar las unidades y los casos del curso."],"conceptos":[{"icono":"Activity","termino":"Insuficiencia cardíaca","definicion":"Síndrome clínico por disfunción cardíaca con síntomas, signos y evidencia de congestión o bajo gasto."},{"icono":"Pill","termino":"Terapia fundamental","definicion":"ARNI o IECA/ARA-II, betabloqueador, antagonista mineralocorticoide e iSGLT2 en FEVI reducida."},{"icono":"ShieldCheck","termino":"Pronóstico","definicion":"La terapia optimizada reduce hospitalizaciones y mortalidad."},{"icono":"Users","termino":"Atención farmacéutica","definicion":"Revisión, educación, titulación y seguimiento para mejorar la seguridad y la adherencia."}],"secciones":[{"titulo":"La IC es un síndrome crónico","parrafos":["La insuficiencia cardíaca es una de las principales causas de hospitalización y mortalidad en adultos. Se produce por disfunción del corazón, que no puede bombear suficiente sangre o lo hace con presiones elevadas. Los síntomas incluyen disnea, fatiga, edema y limitación funcional. El tratamiento no se limita a los diuréticos: incluye fármacos que modifican el pronóstico.","En Colombia, muchos pacientes reciben solo furosemida y no la terapia fundamental. La brecha entre la evidencia y la práctica es una oportunidad para el Químico Farmacéutico, que puede revisar la fórmula, detectar omisiones y proponer optimización."]},{"titulo":"Qué puede hacer el QF","parrafos":["El QF puede verificar la FEVI, la clase funcional, la función renal, el potasio y la presión. Puede detectar fármacos que empeoran la IC, revisar la adherencia, educar sobre peso y sal y coordinar la titulación con el equipo.","La intervención se documenta y se comunica. La meta es que el paciente reciba la terapia que cambia el pronóstico, en dosis toleradas y con seguimiento."]},{"titulo":"Cómo está organizado el curso","parrafos":["La unidad 1 cubre fisiopatología, definición, clasificación y diagnóstico. La unidad 2 revisa los cuatro pilares: ARNI, IECA/ARA-II, betabloqueadores, antagonistas mineralocorticoides e iSGLT2. La unidad 3 trabaja secuenciación, titulación, diuréticos, resistencia diurética, potasio y función renal. La unidad 4 aborda descompensación, terapias adicionales, hierro y FEVI preservada. La unidad 5 cierra con seguridad, interacciones, seguimiento, educación y caso integrador.","Cada clase trae un caso, un mapa y un proceso. Al final, fichas de sacubitrilo/valsartán, dapagliflozina, espironolactona, furosemida y carvedilol."]}],"errores":[{"error":"Tratar solo la congestión.","correccion":"La terapia fundamental cambia el pronóstico."},{"error":"No revisar la FEVI.","correccion":"La clasificación guía el tratamiento."},{"error":"No educar sobre peso y sal.","correccion":"El autocuidado reduce descompensaciones."}],"comprueba":[{"pregunta":"¿Cuáles son los cuatro pilares?","respuesta":"ARNI o IECA/ARA-II, betabloqueador, ARM e iSGLT2."},{"pregunta":"¿Qué hace el QF?","respuesta":"Revisa, detecta omisiones, educa y coordina la titulación."},{"pregunta":"¿Qué guía se usa?","respuesta":"Las guías ESC vigentes y las guías colombianas."}],"resumen":["La IC es un síndrome crónico con alta mortalidad.","La terapia fundamental reduce eventos.","El QF puede cerrar la brecha.","El autocuidado es parte del tratamiento."],"referencias":[{"cita":"European Society of Cardiology. 2026 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2026.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Heart-Failure"},{"cita":"AEMPS-CIMA. Ficha técnica de Entresto 24 mg/26 mg comprimidos recubiertos con película.","url":"https://cima.aemps.es/cima/dochtml/ft/1151058001/FT_1151058001.html"}],"imagenes":[{"ubicacion":"Apertura","descripcion":"Paciente con disnea y edema en una farmacia, con un QF revisando la fórmula de furosemida.","alt":"Químico Farmacéutico en insuficiencia cardíaca"}],"keywords":["curso insuficiencia cardíaca","farmacoterapia insuficiencia cardíaca","rol del químico farmacéutico ic","cuatro pilares insuficiencia cardíaca"],"mapa":{"centro":"QF en insuficiencia cardíaca","ramas":[{"titulo":"Evaluar","icono":"Search","nodos":["FEVI","Síntomas","Congestión"]},{"titulo":"Optimizar","icono":"Pill","nodos":["Cuatro pilares","Titulación","Metas"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Potasio","Función renal","Hipotensión"]},{"titulo":"Educar","icono":"Users","nodos":["Peso","Sal","Signos de alarma"]}]},"proceso":{"titulo":"Cómo abordar la IC en la farmacia","intro":"","pasos":[{"titulo":"Revisar","detalle":"FEVI, síntomas, medicamentos y adherencia.","icono":"Search","evidencia":"Ficha."},{"titulo":"Detectar","detalle":"Omisión de pilares, fármacos que empeoran, barreras.","icono":"AlertTriangle","evidencia":"Problema."},{"titulo":"Proponer","detalle":"Optimización y titulación segura.","icono":"Pill","evidencia":"Nota."},{"titulo":"Educar","detalle":"Peso, sal, signos de alarma y adherencia.","icono":"Users","evidencia":"Educación."},{"titulo":"Seguir","detalle":"Presión, potasio, función renal y síntomas.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Solo furosemida","contexto":"Jaime, 70 años, FEVI 30 %, disnea NYHA III, edemas, solo furosemida. Potasio 4,1, TFG 55.","pregunta":"¿Cuál es la intervención más importante?","opciones":[{"texto":"Aumentar solo la furosemida.","correcta":false,"retro":"El diurético alivia la congestión, pero no cambia el pronóstico."},{"texto":"Revisar la terapia fundamental y proponer inicio de los pilares con titulación.","correcta":true,"retro":"La IC con FEVI reducida requiere terapia que reduce mortalidad y hospitalizaciones."},{"texto":"Suspender la furosemida.","correcta":false,"retro":"La congestión necesita tratamiento."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción al curso: farmacoterapia de la insuficiencia cardíaca en Colombia y guías vigentes a 2026$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Introducción al curso: farmacoterapia de la insuficiencia cardíaca en Colombia y guías vigentes a 2026$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 02. Fisiopatología de la insuficiencia cardíaca: activación neurohormonal, remodelado y congestión
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El círculo que empeora la IC","texto":"Cuando el gasto cardíaco cae, el cuerpo activa el sistema renina-angiotensina y el simpático para mantener la presión. Al principio ayuda, pero a largo plazo retiene sodio, contrae vasos y remodela el corazón. Ese círculo explica por qué los fármacos que bloquean estos sistemas mejoran el pronóstico."},"objetivos":["Explicar la activación neurohormonal en la IC.","Relacionar el remodelado con la progresión.","Reconocer los mecanismos de congestión.","Conectar la fisiopatología con los fármacos."],"conceptos":[{"icono":"Activity","termino":"Remodelado","definicion":"Cambios estructurales y funcionales del corazón que empeoran la función."},{"icono":"Droplets","termino":"Congestión","definicion":"Aumento de presiones y retención de sodio y agua."},{"icono":"Network","termino":"Neurohormonal","definicion":"Activación del SRAA, simpático y otras vías."},{"icono":"Pill","termino":"Bloqueo","definicion":"Los fármacos contrarrestan la activación y mejoran la supervivencia."}],"secciones":[{"titulo":"La activación neurohormonal","parrafos":["La caída del gasto cardíaco reduce la perfusión renal y activa la renina. La angiotensina II y la aldosterona retienen sodio y agua, contraen los vasos y favorecen la fibrosis. El sistema simpático aumenta la frecuencia y la contractilidad, pero también el consumo de oxígeno y la arritmia.","A corto plazo, estos mecanismos mantienen la presión. A largo plazo, empeoran la congestión y el remodelado. Los fármacos que bloquean el SRAA, el simpático y la aldosterona cambian la historia natural."]},{"titulo":"Remodelado y congestión","parrafos":["El remodelado incluye hipertrofia, fibrosis, dilatación y pérdida de contractilidad. La retención de sodio y agua aumenta las presiones de llenado y produce disnea, edema y congestión pulmonar. Los péptidos natriuréticos se elevan como respuesta compensadora.","El tratamiento diurético alivia la congestión, pero no revierte el remodelado. La terapia fundamental lo modula y mejora la supervivencia."]},{"titulo":"Implicaciones farmacológicas","parrafos":["El bloqueo del SRAA con ARNI, IECA o ARA-II, el betabloqueador, el antagonista mineralocorticoide y el iSGLT2 actúan en vías distintas. La combinación es aditiva. La titulación busca dosis toleradas y sostenidas.","El QF puede explicar al paciente por qué necesita varios fármacos aunque se sienta mejor. La adherencia es parte del efecto."]}],"errores":[{"error":"Creer que la IC es solo congestión.","correccion":"La activación neurohormonal y el remodelado son centrales."},{"error":"No explicar el beneficio a largo plazo.","correccion":"La adherencia depende de la comprensión."},{"error":"Suspender pilares por sentirse mejor.","correccion":"El beneficio es crónico."}],"comprueba":[{"pregunta":"¿Qué sistemas se activan?","respuesta":"SRAA, simpático y aldosterona."},{"pregunta":"¿Qué es remodelado?","respuesta":"Cambios estructurales que empeoran la función."},{"pregunta":"¿Qué hace el iSGLT2?","respuesta":"Reduce eventos y congestión con un mecanismo distinto."}],"resumen":["La IC activa sistemas compensadores que dañan.","El remodelado y la congestión progresan.","Los pilares bloquean vías distintas.","La educación mejora la adherencia."],"referencias":[{"cita":"European Society of Cardiology. 2026 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2026.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Heart-Failure"}],"imagenes":[{"ubicacion":"Sección de fisiopatología","descripcion":"Círculo vicioso con bajo gasto, SRAA, simpático, retención y remodelado.","alt":"Fisiopatología de la insuficiencia cardíaca"}],"keywords":["fisiopatología insuficiencia cardíaca","activación neurohormonal ic","remodelado cardíaco","congestión ic"],"mapa":{"centro":"Fisiopatología de la IC","ramas":[{"titulo":"Bajo gasto","icono":"Activity","nodos":["Renina","Simpático","Vasoconstricción"]},{"titulo":"Retención","icono":"Droplets","nodos":["Sodio","Agua","Congestión"]},{"titulo":"Remodelado","icono":"Network","nodos":["Hipertrofia","Fibrosis","Dilatación"]},{"titulo":"Fármacos","icono":"Pill","nodos":["ARNI","Beta","ARM","iSGLT2"]}]},"proceso":{"titulo":"Cómo explicar la IC al paciente","intro":"","pasos":[{"titulo":"Gasto","detalle":"El corazón bombea menos.","icono":"Activity","evidencia":"Explicación."},{"titulo":"Compensación","detalle":"El cuerpo retiene líquido y contrae vasos.","icono":"Droplets","evidencia":"Esquema."},{"titulo":"Consecuencia","detalle":"Congestión y remodelado.","icono":"Network","evidencia":"Síntomas."},{"titulo":"Tratamiento","detalle":"Bloquear la activación y aliviar la congestión.","icono":"Pill","evidencia":"Plan."},{"titulo":"Adherencia","detalle":"Explicar el beneficio a largo plazo.","icono":"Users","evidencia":"Educación."}]},"caso":{"titulo":"Por qué varios fármacos","contexto":"Paciente que se siente mejor con furosemida y quiere suspender el resto.","pregunta":"¿Qué explicar?","opciones":[{"texto":"Que el resto no sirve.","correcta":false,"retro":"Los pilares reducen mortalidad y hospitalizaciones."},{"texto":"Que el diurético alivia, pero los otros bloquean la progresión.","correcta":true,"retro":"La explicación fisiopatológica mejora la adherencia."},{"texto":"Que suspenda todo.","correcta":false,"retro":"Riesgo de descompensación."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Fisiopatología de la insuficiencia cardíaca: activación neurohormonal, remodelado y congestión$t$ AND deleted_at IS NULL
