  -- 03. Definición universal de la IC (2026), etapas A–D, clase funcional NYHA e IC izquierda y derecha
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"No toda IC se ve igual","texto":"Un paciente tiene disnea y crepitantes por congestión pulmonar; otro tiene edema, hepatomegalia y yugulares distendidas. Ambos tienen insuficiencia cardíaca, pero el lado predominante y la etapa son distintos. Clasificar bien guía el tratamiento y el pronóstico."},"objetivos":["Aplicar la definición universal de IC.","Diferenciar las etapas A a D.","Clasificar la clase funcional NYHA.","Reconocer IC izquierda, derecha y biventricular."],"conceptos":[{"icono":"Activity","termino":"Definición universal","definicion":"Síntomas y signos de IC con evidencia de disfunción cardíaca, elevación de péptidos o congestión."},{"icono":"Layers","termino":"Etapas A-D","definicion":"Desde riesgo hasta IC avanzada."},{"icono":"Users","termino":"NYHA","definicion":"Clase funcional I-IV según limitación de la actividad."},{"icono":"Network","termino":"Lado","definicion":"Izquierda, derecha o biventricular según la congestión."}],"secciones":[{"titulo":"Definición y etapas","parrafos":["La definición universal de IC combina síntomas y signos con evidencia de disfunción cardíaca, elevación de péptidos natriuréticos o congestión. Las etapas A a D describen el riesgo y la progresión: A es riesgo, B es enfermedad cardíaca estructural sin síntomas, C es IC sintomática y D es IC avanzada.","La etapa no es lo mismo que la clase funcional. Un paciente en etapa C puede estar en NYHA II o III. La clasificación permite anticipar el tratamiento y el seguimiento."]},{"titulo":"NYHA y lado","parrafos":["La clase NYHA va de I (sin limitación) a IV (síntomas en reposo). La IC izquierda predomina con disnea, ortopnea y crepitantes; la derecha con edema, hepatomegalia, ingurgitación yugular y ascitis. Muchos pacientes tienen congestión biventricular.","La FEVI clasifica la IC en reducida, levemente reducida y preservada. La terapia fundamental depende de la FEVI y de la comorbilidad."]},{"titulo":"Aplicación","parrafos":["La clasificación se documenta en la historia y se revisa con los síntomas. La etapa A y B permiten prevención; la C y D requieren tratamiento y seguimiento estrecho.","El QF puede educar sobre la etapa y la clase funcional. La comprensión mejora la adherencia."]}],"errores":[{"error":"Confundir etapa con NYHA.","correccion":"Son clasificaciones distintas."},{"error":"No evaluar el lado predominante.","correccion":"Guía el tratamiento de la congestión."},{"error":"No documentar la FEVI.","correccion":"La terapia depende de ella."}],"comprueba":[{"pregunta":"¿Qué es etapa C?","respuesta":"IC sintomática con enfermedad estructural."},{"pregunta":"¿Qué es NYHA III?","respuesta":"Limitación marcada por síntomas con actividad leve."},{"pregunta":"¿Qué diferencia IC izquierda y derecha?","respuesta":"La congestión pulmonar versus sistémica."}],"resumen":["La definición universal integra síntomas y evidencia.","Las etapas A-D describen progresión.","NYHA describe limitación funcional.","La FEVI guía la terapia."],"referencias":[{"cita":"European Society of Cardiology. 2026 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2026.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Heart-Failure"}],"imagenes":[{"ubicacion":"Sección de clasificación","descripcion":"Tabla de etapas A-D y clase NYHA I-IV con ejemplos.","alt":"Clasificación de la insuficiencia cardíaca"}],"keywords":["definición insuficiencia cardíaca","etapas a b c d ic","nyha insuficiencia cardíaca","ic izquierda derecha"],"mapa":{"centro":"Clasificación de la IC","ramas":[{"titulo":"Etapas","icono":"Layers","nodos":["A riesgo","B preclínica","C sintomática","D avanzada"]},{"titulo":"NYHA","icono":"Users","nodos":["I sin límite","II leve","III marcada","IV reposo"]},{"titulo":"Lado","icono":"Network","nodos":["Izquierda","Derecha","Biventricular"]},{"titulo":"FEVI","icono":"Activity","nodos":["Reducida","Levemente reducida","Preservada"]}]},"proceso":{"titulo":"Cómo clasificar la IC","intro":"","pasos":[{"titulo":"Confirmar","detalle":"Síntomas, signos y evidencia.","icono":"Search","evidencia":"Evaluación."},{"titulo":"Etapa","detalle":"A, B, C o D.","icono":"Layers","evidencia":"Clasificación."},{"titulo":"NYHA","detalle":"I a IV.","icono":"Users","evidencia":"Clase."},{"titulo":"FEVI","detalle":"Reducida, levemente reducida o preservada.","icono":"Activity","evidencia":"Eco."},{"titulo":"Plan","detalle":"Tratamiento y seguimiento.","icono":"Target","evidencia":"Plan."}]},"caso":{"titulo":"Disnea y edemas","contexto":"Paciente con disnea a pequeños esfuerzos, edema y yugulares distendidas.","pregunta":"¿Qué clasificación es más probable?","opciones":[{"texto":"NYHA I y etapa A.","correcta":false,"retro":"Hay síntomas y congestión."},{"texto":"NYHA III, etapa C, probable biventricular.","correcta":true,"retro":"Los síntomas limitan la actividad y hay congestión."},{"texto":"Sin IC.","correcta":false,"retro":"El cuadro es compatible con IC."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
