  END IF;

  -- 04. Clasificación por FEVI: FEVIr, FEVIlr, FEVIp y FEVI mejorada — de ESC 2021/2023 a ESC 2026
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La FEVI no es un número fijo","texto":"Un paciente tenía FEVI de 32 % y después del tratamiento llegó a 45 %. ¿Sigue teniendo IC con FEVI reducida? La categoría “FEVI mejorada” reconoce que la fracción puede recuperarse, pero el riesgo persiste. Clasificar correctamente evita suspender fármacos que siguen siendo necesarios."},"objetivos":["Diferenciar FEVI reducida, levemente reducida, preservada y mejorada.","Aplicar los puntos de corte.","Reconocer el significado pronóstico de la mejoría.","Relacionar la categoría con el tratamiento."],"conceptos":[{"icono":"Activity","termino":"FEVIr","definicion":"FEVI ≤40 %; terapia fundamental con evidencia."},{"icono":"Activity","termino":"FEVIlr","definicion":"FEVI 41-49 %; tratamiento individualizado."},{"icono":"Activity","termino":"FEVIp","definicion":"FEVI ≥50 %; iSGLT2 y manejo de comorbilidades."},{"icono":"RefreshCw","termino":"FEVI mejorada","definicion":"Aumento de al menos 10 puntos desde una FEVI reducida, con riesgo persistente."}],"secciones":[{"titulo":"Puntos de corte","parrafos":["La IC con FEVI reducida se define con FEVI ≤40 %. La levemente reducida, entre 41 y 49 %. La preservada, ≥50 %. La FEVI mejorada se describe cuando hay un aumento de al menos 10 puntos desde una FEVI reducida y ya no cumple el criterio de reducida, aunque el riesgo cardiovascular y de descompensación persiste.","Las guías ESC 2021 y 2023 consolidaron estas categorías; la ESC 2026 actualiza el enfoque y refuerza el tratamiento por comorbilidad. La clasificación no es solo académica: guía la elección y la titulación."]},{"titulo":"Implicaciones","parrafos":["En FEVI reducida, los cuatro pilares tienen evidencia robusta. En FEVI levemente reducida, el tratamiento se individualiza y los iSGLT2 tienen un papel. En FEVI preservada, los iSGLT2 reducen hospitalizaciones y se tratan comorbilidades como obesidad, hipertensión, diabetes y fibrilación auricular.","En FEVI mejorada, no se deben suspender los fármacos que lograron la recuperación sin una evaluación cuidadosa. El riesgo de recaída existe."]},{"titulo":"Seguimiento","parrafos":["La FEVI se reevalúa con ecocardiograma cuando hay cambios clínicos o después de un tiempo de tratamiento. La mejoría no significa curación. La educación y la adherencia siguen siendo clave.","El QF puede recordar la categoría y el plan en cada contacto."]}],"errores":[{"error":"Suspender terapia por mejoría de FEVI.","correccion":"El riesgo persiste."},{"error":"Confundir FEVI preservada con ausencia de IC.","correccion":"La IC preservada es un síndrome."},{"error":"No reevaluar la FEVI.","correccion":"La categoría puede cambiar."}],"comprueba":[{"pregunta":"¿Qué FEVI define IC reducida?","respuesta":"≤40 %."},{"pregunta":"¿Qué es FEVI mejorada?","respuesta":"Aumento de al menos 10 puntos desde una FEVI reducida."},{"pregunta":"¿Se suspende el tratamiento?","respuesta":"No sin evaluación; el riesgo persiste."}],"resumen":["La FEVI clasifica la IC.","La FEVI mejorada no es curación.","La terapia depende de la categoría.","La reevaluación es parte del seguimiento."],"referencias":[{"cita":"European Society of Cardiology. 2026 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2026.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Heart-Failure"}],"imagenes":[{"ubicacion":"Sección de categorías","descripcion":"Escala de FEVI con cuatro categorías y sus tratamientos.","alt":"Clasificación de la insuficiencia cardíaca por FEVI"}],"keywords":["fevi reducida","fevi preservada","fevi levemente reducida","fevi mejorada","clasificación insuficiencia cardíaca"],"mapa":{"centro":"Clasificación por FEVI","ramas":[{"titulo":"Reducida","icono":"Activity","nodos":["≤40 %","Cuatro pilares","Titular"]},{"titulo":"Levemente reducida","icono":"Activity","nodos":["41-49 %","Individualizar","iSGLT2"]},{"titulo":"Preservada","icono":"Activity","nodos":["≥50 %","iSGLT2","Comorbilidad"]},{"titulo":"Mejorada","icono":"RefreshCw","nodos":["≥10 puntos","Mantener","Seguir"]}]},"proceso":{"titulo":"Cómo clasificar por FEVI","intro":"","pasos":[{"titulo":"Medir","detalle":"Ecocardiograma y FEVI.","icono":"Activity","evidencia":"Resultado."},{"titulo":"Clasificar","detalle":"Reducida, levemente reducida o preservada.","icono":"Layers","evidencia":"Categoría."},{"titulo":"Reevaluar","detalle":"Mejoría y cambios.","icono":"RefreshCw","evidencia":"Control."},{"titulo":"Tratar","detalle":"Según categoría y comorbilidad.","icono":"Pill","evidencia":"Plan."},{"titulo":"Seguir","detalle":"Síntomas y adherencia.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"FEVI 32 que subió a 45","contexto":"Paciente con FEVI inicial 32 %, tratamiento óptimo y FEVI actual 45 %, asintomático.","pregunta":"¿Qué hacer con el tratamiento?","opciones":[{"texto":"Suspender todo porque mejoró.","correcta":false,"retro":"El riesgo persiste; la suspensión puede causar recaída."},{"texto":"Mantener la terapia y reevaluar, con seguimiento.","correcta":true,"retro":"La FEVI mejorada requiere continuidad."},{"texto":"Añadir un cuarto diurético.","correcta":false,"retro":"No es necesario."}]}}$j$::jsonb;
