  -- 05. Diagnóstico de la IC: síntomas y signos, péptidos natriuréticos, ECG, ecocardiograma y búsqueda de la causa
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La disnea que no era EPOC","texto":"Un paciente con disnea y sibilancias es tratado como EPOC durante meses. Un ecocardiograma revela disfunción ventricular y una FEVI de 28 %. El diagnóstico de insuficiencia cardíaca requiere síntomas, evidencia y búsqueda de la causa. Los péptidos natriuréticos y el ecocardiograma son claves."},"objetivos":["Reconocer síntomas y signos de IC.","Interpretar péptidos natriuréticos.","Aplicar ECG, ecocardiograma y estudios de causa.","Identificar diagnósticos diferenciales."],"conceptos":[{"icono":"Search","termino":"Péptidos natriuréticos","definicion":"BNP o NT-proBNP elevados apoyan el diagnóstico; valores bajos lo hacen improbable."},{"icono":"Activity","termino":"Ecocardiograma","definicion":"Evalúa FEVI, válvulas, paredes y presiones."},{"icono":"Network","termino":"ECG","definicion":"Puede mostrar hipertrofia, arritmia, isquemia o bloqueos."},{"icono":"Target","termino":"Causa","definicion":"Isquemia, valvulopatía, hipertensión, miocardiopatía o tóxicos."}],"secciones":[{"titulo":"Clínica y péptidos","parrafos":["Los síntomas incluyen disnea, ortopnea, disnea paroxística nocturna, fatiga y edema. Los signos incluyen crepitantes, ingurgitación yugular, tercer ruido, edema y hepatomegalia. Ninguno es exclusivo; la combinación con evidencia objetiva es clave.","Los péptidos natriuréticos ayudan cuando el diagnóstico es incierto. Valores bajos hacen improbable la IC; valores altos apoyan pero no son específicos. La obesidad, la edad y la función renal modifican su interpretación."]},{"titulo":"Estudios","parrafos":["El ECG puede mostrar hipertrofia, arritmia, isquemia o bloqueos. El ecocardiograma evalúa la FEVI, las válvulas, el grosor y las presiones. La radiografía puede mostrar congestión. La búsqueda de causa incluye isquemia, hipertensión, valvulopatía, miocardiopatía, alcohol, quimioterapia y enfermedades infiltrativas.","El diagnóstico temprano permite iniciar la terapia fundamental y evitar descompensaciones."]},{"titulo":"Diagnóstico diferencial","parrafos":["La disnea puede deberse a EPOC, asma, anemia, obesidad, embolia pulmonar o enfermedad renal. La IC puede coexistir con otras condiciones. La evaluación integral evita tratamientos incorrectos.","El QF puede revisar los medicamentos que causan o empeoran la IC y educar sobre la importancia del ecocardiograma."]}],"errores":[{"error":"Atribuir toda disnea a EPOC.","correccion":"La IC puede simular EPOC."},{"error":"Interpretar péptidos sin contexto.","correccion":"Obesidad y función renal afectan."},{"error":"No buscar la causa.","correccion":"La causa guía el tratamiento."}],"comprueba":[{"pregunta":"¿Qué péptido apoya el diagnóstico?","respuesta":"BNP o NT-proBNP."},{"pregunta":"¿Qué evalúa el ecocardiograma?","respuesta":"FEVI, válvulas y presiones."},{"pregunta":"¿Qué causas se buscan?","respuesta":"Isquemia, hipertensión, valvulopatía, tóxicos."}],"resumen":["La IC se diagnostica con clínica y evidencia.","Los péptidos ayudan en casos inciertos.","El ecocardiograma es clave.","La causa guía el tratamiento."],"referencias":[{"cita":"European Society of Cardiology. 2026 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2026.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Heart-Failure"}],"imagenes":[{"ubicacion":"Sección de diagnóstico","descripcion":"Paciente con disnea, ecocardiograma y resultado de BNP.","alt":"Diagnóstico de insuficiencia cardíaca"}],"keywords":["diagnóstico insuficiencia cardíaca","bnp nt-probnp","ecocardiograma ic","disnea ic"],"mapa":{"centro":"Diagnóstico de IC","ramas":[{"titulo":"Síntomas","icono":"Users","nodos":["Disnea","Fatiga","Edema"]},{"titulo":"Péptidos","icono":"Search","nodos":["BNP","NT-proBNP","Valorar"]},{"titulo":"Imagen","icono":"Activity","nodos":["Eco","FEVI","Válvulas"]},{"titulo":"Causa","icono":"Target","nodos":["Isquemia","Hipertensión","Tóxicos"]}]},"proceso":{"titulo":"Cómo diagnosticar la IC","intro":"","pasos":[{"titulo":"Sospechar","detalle":"Síntomas y signos.","icono":"Search","evidencia":"Clínica."},{"titulo":"Péptidos","detalle":"BNP o NT-proBNP.","icono":"TestTube","evidencia":"Resultado."},{"titulo":"Imagen","detalle":"Ecocardiograma.","icono":"Activity","evidencia":"FEVI."},{"titulo":"Causa","detalle":"Isquemia, válvulas, tóxicos.","icono":"Target","evidencia":"Estudios."},{"titulo":"Clasificar","detalle":"FEVI y etapa.","icono":"Layers","evidencia":"Diagnóstico."}]},"caso":{"titulo":"Disnea y sibilancias","contexto":"Paciente con disnea, sibilancias y edema; tratamiento previo como EPOC sin mejoría.","pregunta":"¿Qué estudio es clave?","opciones":[{"texto":"Solo aumentar el broncodilatador.","correcta":false,"retro":"Puede ser IC."},{"texto":"Ecocardiograma y péptidos natriuréticos.","correcta":true,"retro":"Confirman disfunción y apoyan el diagnóstico."},{"texto":"No hacer nada.","correcta":false,"retro":"El diagnóstico es necesario."}]}}$j$::jsonb;
