  -- 06. Caso: mujer de 68 años en Barranquilla con disnea y edemas — del diagnóstico a la clasificación y la revisión de la fórmula
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La fórmula que no incluía la IC","texto":"Una mujer de 68 años llega con disnea, edemas y presión alta. Toma amlodipino, hidroclorotiazida y un AINE. El ecocardiograma muestra FEVI de 35 %. La fórmula no incluye ningún fármaco para la IC. El caso exige diagnosticar, clasificar y revisar la medicación completa. La intervención debe priorizar la suspensión del AINE y el inicio de la terapia fundamental, con educación y seguimiento."},"objetivos":["Integrar diagnóstico y clasificación en un caso real.","Revisar fármacos que empeoran la IC.","Proponer el inicio de la terapia fundamental.","Diseñar educación y seguimiento."],"conceptos":[{"icono":"Activity","termino":"FEVI 35 %","definicion":"IC con FEVI reducida."},{"icono":"AlertTriangle","termino":"AINE","definicion":"Retiene sodio y empeora la congestión y la función renal."},{"icono":"Pill","termino":"Terapia fundamental","definicion":"ARNI o IECA/ARA-II, beta, ARM e iSGLT2."},{"icono":"Users","termino":"Educación","definicion":"Peso, sal, signos de alarma y adherencia."}],"secciones":[{"titulo":"Evaluación","parrafos":["La paciente tiene IC con FEVI reducida, clase funcional probablemente III por disnea y edemas. El AINE empeora la congestión y la función renal. La fórmula actual no incluye terapia fundamental. Se revisan presión, potasio, TFG y síntomas.","Se suspende el AINE y se propone iniciar los pilares de forma escalonada, con control de presión, potasio y función renal. La educación incluye peso diario y sal."]},{"titulo":"Plan","parrafos":["Se puede iniciar un ARNI o IECA/ARA-II, un betabloqueador con evidencia, un ARM y un iSGLT2. La secuencia depende de la presión, la función renal y el potasio. La titulación se hace con seguimiento.","El QF documenta la intervención y coordina con el equipo. La paciente debe entender por qué necesita varios fármacos."]},{"titulo":"Seguimiento","parrafos":["Se revisan peso, presión, síntomas, potasio y TFG. La adherencia y la educación son clave. La meta es reducir hospitalizaciones y mejorar la calidad de vida.","La revisión de la fórmula debe repetirse en cada contacto. La paciente debe conocer los signos de alarma, el peso diario y la importancia de no suspender los pilares sin consultar nunca."]}],"errores":[{"error":"Mantener AINE.","correccion":"Empeora la congestión y el riñón."},{"error":"No iniciar pilares.","correccion":"La FEVI reducida los requiere."},{"error":"No educar.","correccion":"El autocuidado es clave."}],"comprueba":[{"pregunta":"¿Qué fármaco empeora la IC?","respuesta":"El AINE."},{"pregunta":"¿Qué pilares se inician?","respuesta":"ARNI/IECA/ARA-II, beta, ARM e iSGLT2."},{"pregunta":"¿Qué se controla?","respuesta":"Peso, presión, potasio y TFG."}],"resumen":["La FEVI 35 define IC reducida.","El AINE se suspende.","Los pilares se inician de forma escalonada.","El seguimiento es clave."],"referencias":[{"cita":"European Society of Cardiology. 2026 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2026.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Heart-Failure"},{"cita":"AEMPS-CIMA. Ficha técnica de Entresto 24 mg/26 mg comprimidos recubiertos con película.","url":"https://cima.aemps.es/cima/dochtml/ft/1151058001/FT_1151058001.html"}],"imagenes":[{"ubicacion":"Sección del caso","descripcion":"Paciente con edemas, ecocardiograma con FEVI 35 y fórmula sin pilares.","alt":"Caso de insuficiencia cardíaca en Barranquilla"}],"keywords":["caso insuficiencia cardíaca","fevi 35 tratamiento","aine insuficiencia cardíaca","terapia fundamental ic"],"mapa":{"centro":"Caso Barranquilla","ramas":[{"titulo":"Diagnóstico","icono":"Search","nodos":["Disnea","Edema","FEVI 35"]},{"titulo":"Fármacos","icono":"AlertTriangle","nodos":["AINE","Amlodipino","Tiazida"]},{"titulo":"Tratamiento","icono":"Pill","nodos":["ARNI","Beta","ARM","iSGLT2"]},{"titulo":"Seguimiento","icono":"CalendarClock","nodos":["Peso","Potasio","TFG"]}]},"proceso":{"titulo":"Abordaje del caso","intro":"","pasos":[{"titulo":"Clasificar","detalle":"FEVI 35, NYHA III, etapa C.","icono":"Layers","evidencia":"Diagnóstico."},{"titulo":"Revisar","detalle":"AINE y fármacos actuales.","icono":"Search","evidencia":"Lista."},{"titulo":"Iniciar","detalle":"Pilares escalonados.","icono":"Pill","evidencia":"Plan."},{"titulo":"Educar","detalle":"Peso, sal y signos de alarma.","icono":"Users","evidencia":"Educación."},{"titulo":"Seguir","detalle":"Potasio, TFG y síntomas.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"AINE y FEVI 35","contexto":"Mujer de 68 años, FEVI 35 %, disnea y edemas, toma AINE y no tiene terapia fundamental.","pregunta":"¿Qué hacer primero?","opciones":[{"texto":"Aumentar la tiazida.","correcta":false,"retro":"No aborda la IC ni el AINE."},{"texto":"Suspender el AINE y proponer inicio de la terapia fundamental.","correcta":true,"retro":"Se trata la causa de empeoramiento y se optimiza."},{"texto":"Solo diurético.","correcta":false,"retro":"No cambia el pronóstico."}]}}$j$::jsonb;
