  -- 07. Introducción a la unidad: la terapia médica fundamental de la IC con FEVI reducida (los cuatro pilares)
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Cuatro pilares, no uno","texto":"Durante años, la IC con FEVI reducida se trataba con un IECA y un betabloqueador. Hoy la evidencia muestra que ARNI o IECA/ARA-II, betabloqueador, antagonista mineralocorticoide e iSGLT2 reducen mortalidad y hospitalizaciones. La combinación es el estándar, no la excepción."},"objetivos":["Identificar los cuatro pilares.","Reconocer el beneficio de cada grupo.","Aplicar criterios de inicio y titulación.","Reconocer barreras y soluciones."],"conceptos":[{"icono":"Pill","termino":"ARNI","definicion":"Sacubitrilo/valsartán; preferido en FEVI reducida cuando es posible."},{"icono":"Activity","termino":"Betabloqueador","definicion":"Bisoprolol, carvedilol, metoprolol succinato o nebivolol con evidencia."},{"icono":"Droplets","termino":"ARM","definicion":"Espironolactona, eplerenona o finerenona."},{"icono":"Gauge","termino":"iSGLT2","definicion":"Dapagliflozina o empagliflozina; reducen eventos y congestión."}],"secciones":[{"titulo":"Los cuatro pilares","parrafos":["El primer pilar es el bloqueo del sistema renina-angiotensina con ARNI o, si no está disponible, IECA o ARA-II. El segundo es un betabloqueador con evidencia. El tercero es un antagonista mineralocorticoide. El cuarto es un iSGLT2. Cada uno reduce mortalidad y hospitalizaciones, y sus efectos son aditivos.","La terapia debe iniciarse en dosis bajas y titularse. La secuencia puede ser simultánea o escalonada, según la presión, la función renal, el potasio y la tolerancia."]},{"titulo":"Barreras","parrafos":["Las barreras incluyen hipotensión, bradicardia, hiperpotasemia, deterioro renal, costo y falta de coordinación. La mayoría se manejan con titulación cuidadosa y seguimiento, no con abandono del fármaco.","El QF puede detectar barreras y proponer soluciones. La educación sobre el beneficio a largo plazo mejora la adherencia."]},{"titulo":"Metas","parrafos":["La meta es alcanzar dosis toleradas de los cuatro pilares y controlar la congestión. La FEVI puede mejorar, pero el tratamiento no se suspende automáticamente.","La revisión periódica y la comunicación con el equipo son esenciales."]}],"errores":[{"error":"Quedarse con dos pilares.","correccion":"Los cuatro son el estándar."},{"error":"No titular.","correccion":"La dosis baja no alcanza el beneficio completo."},{"error":"Suspender por una barrera manejable.","correccion":"Se ajusta y se sigue."}],"comprueba":[{"pregunta":"¿Cuáles son los cuatro pilares?","respuesta":"ARNI/IECA/ARA-II, beta, ARM e iSGLT2."},{"pregunta":"¿Cómo se titulan?","respuesta":"Dosis bajas y aumento gradual con control."},{"pregunta":"¿Qué barreras son frecuentes?","respuesta":"Hipotensión, bradicardia, hiperpotasemia yTFG."}],"resumen":["La IC reducida requiere cuatro pilares.","El beneficio es aditivo.","La titulación es segura con control.","No se abandona por barreras manejables."],"referencias":[{"cita":"European Society of Cardiology. 2026 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2026.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Heart-Failure"}],"imagenes":[{"ubicacion":"Sección de pilares","descripcion":"Cuatro columnas con ARNI/IECA, beta, ARM e iSGLT2.","alt":"Cuatro pilares del tratamiento de la IC con FEVI reducida"}],"keywords":["cuatro pilares insuficiencia cardíaca","terapia fundamental ic","arni beta arm isglt2"],"mapa":{"centro":"Cuatro pilares","ramas":[{"titulo":"ARNI/IECA","icono":"Pill","nodos":["Sacubitrilo/valsartán","Enalapril","Losartán"]},{"titulo":"Beta","icono":"Activity","nodos":["Bisoprolol","Carvedilol","Metoprolol"]},{"titulo":"ARM","icono":"Droplets","nodos":["Espironolactona","Eplerenona","Finerenona"]},{"titulo":"iSGLT2","icono":"Gauge","nodos":["Dapagliflozina","Empagliflozina"]}]},"proceso":{"titulo":"Cómo iniciar los pilares","intro":"","pasos":[{"titulo":"Evaluar","detalle":"Presión, TFG, potasio y síntomas.","icono":"Search","evidencia":"Evaluación."},{"titulo":"Iniciar","detalle":"Dosis bajas de los pilares.","icono":"Pill","evidencia":"Plan."},{"titulo":"Titular","detalle":"Cada 2-4 semanas.","icono":"RefreshCw","evidencia":"Esquema."},{"titulo":"Controlar","detalle":"Potasio, TFG, presión y síntomas.","icono":"LineChart","evidencia":"Resultados."},{"titulo":"Mantener","detalle":"Dosis toleradas y adherencia.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"Solo IECA y beta","contexto":"Paciente con FEVI 30 %, IECA y betabloqueador, sin ARM ni iSGLT2.","pregunta":"¿Qué hacer?","opciones":[{"texto":"Mantener solo dos pilares.","correcta":false,"retro":"Faltan ARM e iSGLT2, con beneficio demostrado."},{"texto":"Añadir ARM e iSGLT2 si no hay contraindicación.","correcta":true,"retro":"La combinación completa mejora el pronóstico."},{"texto":"Suspender el beta.","correcta":false,"retro":"El beta tiene beneficio."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción a la unidad: la terapia médica fundamental de la IC con FEVI reducida (los cuatro pilares)$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Introducción a la unidad: la terapia médica fundamental de la IC con FEVI reducida (los cuatro pilares)$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
