  -- 08. ARNI: sacubitrilo/valsartán — mecanismo, inicio, titulación y transición desde IECA
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"El cambio que exige esperar 36 horas","texto":"Un paciente con enalapril y FEVI reducida va a cambiar a sacubitrilo/valsartán. El cambio no es inmediato: hay que suspender el IECA y esperar al menos 36 horas para evitar angioedema. La transición mal hecha puede ser peligrosa. Respetar el intervalo y controlar la presión y el potasio evita complicaciones."},"objetivos":["Explicar el mecanismo del ARNI.","Aplicar el inicio y la titulación.","Realizar la transición desde IECA de forma segura.","Reconocer efectos adversos y controles."],"conceptos":[{"icono":"Pill","termino":"Sacubitrilo","definicion":"Inhibe la neprilisina y aumenta los péptidos natriuréticos."},{"icono":"Activity","termino":"Valsartán","definicion":"Bloquea el receptor AT1 y contrarresta la angiotensina II."},{"icono":"Timer","termino":"36 horas","definicion":"Espera mínima tras suspender un IECA antes de iniciar el ARNI."},{"icono":"AlertTriangle","termino":"Angioedema","definicion":"Riesgo si no se respeta la transición."}],"secciones":[{"titulo":"Mecanismo y beneficio","parrafos":["El sacubitrilo inhibe la neprilisina, que degrada los péptidos natriuréticos, y el valsartán bloquea el receptor AT1. El resultado es vasodilatación, menos retención de sodio y menor remodelado. En FEVI reducida, el ARNI reduce mortalidad y hospitalizaciones más que un IECA.","Se prefiere en pacientes que toleran un IECA o ARA-II y tienen FEVI reducida. No se combina con IECA."]},{"titulo":"Inicio y transición","parrafos":["Se inicia con 24/26 mg cada 12 horas en pacientes estables con presión adecuada. La dosis se titula cada dos a cuatro semanas hasta 97/103 mg cada 12 horas, según tolerancia. En hipotensión, se ajustan diuréticos y otras dosis.","Si el paciente viene de un IECA, se suspende y se espera al menos 36 horas antes de iniciar el ARNI. Si viene de un ARA-II, no se requiere esa espera. Se controlan presión, potasio y función renal."]},{"titulo":"Seguridad","parrafos":["Los efectos adversos incluyen hipotensión, hiperpotasemia, deterioro renal y angioedema. Se controlan potasio y creatinina. No se usa en embarazo ni en antecedente de angioedema relacionado con IECA.","La educación incluye no combinar con IECA y reportar hinchazón de labios o lengua."]}],"errores":[{"error":"Combinar IECA y ARNI.","correccion":"Contraindicado."},{"error":"No esperar 36 horas.","correccion":"Riesgo de angioedema."},{"error":"Titular sin controlar presión.","correccion":"Riesgo de hipotensión."}],"comprueba":[{"pregunta":"¿Qué inhibe el sacubitrilo?","respuesta":"La neprilisina."},{"pregunta":"¿Cuánto esperar tras IECA?","respuesta":"Al menos 36 horas."},{"pregunta":"¿Qué se controla?","respuesta":"Presión, potasio y función renal."}],"resumen":["ARNI: neprilisina + AT1.","Reduce mortalidad y hospitalizaciones.","Esperar 36 horas tras IECA.","Titular con control."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Entresto 24 mg/26 mg comprimidos recubiertos con película.","url":"https://cima.aemps.es/cima/dochtml/ft/1151058001/FT_1151058001.html"},{"cita":"European Society of Cardiology. 2026 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2026.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Heart-Failure"}],"imagenes":[{"ubicacion":"Sección de transición","descripcion":"Reloj de 36 horas entre un IECA y el ARNI.","alt":"Transición de IECA a sacubitrilo/valsartán"}],"keywords":["sacubitrilo valsartán","arni insuficiencia cardíaca","transición ieca arni","entresto dosis"],"mapa":{"centro":"ARNI","ramas":[{"titulo":"Mecanismo","icono":"Pill","nodos":["Neprilisina","Péptidos","AT1"]},{"titulo":"Inicio","icono":"CalendarClock","nodos":["24/26 mg","Cada 12 h","Titular"]},{"titulo":"Transición","icono":"Timer","nodos":["Suspender IECA","36 h","Iniciar"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Hipotensión","Potasio","TFG"]}]},"proceso":{"titulo":"Cómo iniciar ARNI","intro":"","pasos":[{"titulo":"Confirmar","detalle":"FEVI reducida y tolerancia a IECA/ARA-II.","icono":"Target","evidencia":"Indicación."},{"titulo":"Suspender IECA","detalle":"Esperar 36 horas.","icono":"Timer","evidencia":"Registro."},{"titulo":"Iniciar","detalle":"24/26 mg cada 12 horas.","icono":"Pill","evidencia":"Dosis."},{"titulo":"Titular","detalle":"Cada 2-4 semanas.","icono":"RefreshCw","evidencia":"Esquema."},{"titulo":"Controlar","detalle":"Presión, potasio y TFG.","icono":"LineChart","evidencia":"Control."}]},"caso":{"titulo":"Cambio desde enalapril","contexto":"Paciente con enalapril, FEVI 28 % y presión 118/72. Se decide cambiar a ARNI.","pregunta":"¿Qué hacer?","opciones":[{"texto":"Iniciar ARNI el mismo día.","correcta":false,"retro":"Debe esperar 36 horas tras suspender el IECA."},{"texto":"Suspender enalapril, esperar 36 horas e iniciar ARNI con titulación.","correcta":true,"retro":"La transición segura evita angioedema."},{"texto":"Combinar enalapril y ARNI.","correcta":false,"retro":"No se combinan."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
