  -- 09. IECA y ARA-II en la IC con FEVI reducida: cuándo usarlos, dosis objetivo y efectos adversos
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Cuando el ARNI no está disponible","texto":"No todos los pacientes pueden acceder al ARNI. Los IECA y ARA-II siguen siendo pilares cuando el ARNI no está disponible o no se tolera. La dosis objetivo y el control de potasio y función renal son parte del tratamiento. La titulación debe ser gradual y sostenida, con educación sobre tos, angioedema y adherencia."},"objetivos":["Reconocer el lugar de IECA y ARA-II.","Aplicar dosis objetivo y titulación.","Manejar tos, angioedema e hiperpotasemia.","Elegir según tolerancia y acceso."],"conceptos":[{"icono":"Pill","termino":"IECA","definicion":"Enalapril, lisinopril, ramipril; reducen mortalidad en FEVI reducida."},{"icono":"Pill","termino":"ARA-II","definicion":"Losartán, valsartán, candesartán; alternativa si hay tos."},{"icono":"Target","termino":"Dosis objetivo","definicion":"Dosis tolerada que ha demostrado beneficio."},{"icono":"AlertTriangle","termino":"Efectos","definicion":"Tos, angioedema, hiperpotasemia y deterioro renal."}],"secciones":[{"titulo":"Cuándo usarlos","parrafos":["En FEVI reducida, un IECA o ARA-II es parte de la terapia fundamental cuando no se usa ARNI. El ARNI se prefiere si el paciente es elegible. No se combinan IECA y ARA-II. Se controlan potasio y función renal.","La dosis se titula hasta la dosis objetivo tolerada. La evidencia depende de alcanzar dosis adecuadas, no solo de iniciar."]},{"titulo":"Efectos adversos","parrafos":["La tos seca es frecuente con IECA; el angioedema es raro pero grave. La hiperpotasemia y el deterioro renal requieren control. En insuficiencia renal o deshidratación, el riesgo aumenta.","Si hay tos intolerable, se cambia a ARA-II. Si hay angioedema, se suspende y no se reintroduce un IECA."]},{"titulo":"Acceso y adherencia","parrafos":["El costo y la cobertura influyen. El QF puede revisar alternativas y educar. La adherencia es clave para el beneficio.","La titulación debe ser gradual y con seguimiento. La educación incluye reconocer la tos, el angioedema y la hiperpotasemia, y no combinar IECA con ARA-II. La revisión debe incluir potasio, creatinina y presión, y la dosis se ajusta según la tolerancia. La adherencia y la educación sobre efectos adversos son parte del éxito. La revisión periódica permite ajustar la dosis objetivo."]}],"errores":[{"error":"No alcanzar dosis objetivo.","correccion":"La titulación es parte del beneficio."},{"error":"Combinar IECA y ARA-II.","correccion":"No se recomienda."},{"error":"No controlar potasio.","correccion":"Riesgo de hiperpotasemia."}],"comprueba":[{"pregunta":"¿Cuándo se prefiere ARNI?","respuesta":"Cuando el paciente es elegible y tiene acceso."},{"pregunta":"¿Qué alternativa si hay tos?","respuesta":"Un ARA-II."},{"pregunta":"¿Qué se controla?","respuesta":"Potasio y función renal."}],"resumen":["IECA/ARA-II son pilares si no hay ARNI.","La dosis objetivo importa.","La tos se maneja con ARA-II.","Potasio y TFG se controlan."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Enalapril maleato.","url":"https://cima.aemps.es/cima/dochtml/ft/73300/FT_73300.html"},{"cita":"European Society of Cardiology. 2026 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2026.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Heart-Failure"}],"imagenes":[{"ubicacion":"Sección de elección","descripcion":"Comparación ARNI, IECA y ARA-II en FEVI reducida.","alt":"IECA y ARA-II en insuficiencia cardíaca"}],"keywords":["ieca insuficiencia cardíaca","ara-ii insuficiencia cardíaca","dosis objetivo enalapril","tos ieca ic"],"mapa":{"centro":"IECA/ARA-II","ramas":[{"titulo":"IECA","icono":"Pill","nodos":["Enalapril","Lisinopril","Ramipril"]},{"titulo":"ARA-II","icono":"Pill","nodos":["Losartán","Valsartán","Candesartán"]},{"titulo":"Dosis","icono":"Target","nodos":["Inicio bajo","Titular","Dosis objetivo"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Tos","Angioedema","Potasio"]}]},"proceso":{"titulo":"Cómo titular IECA/ARA-II","intro":"","pasos":[{"titulo":"Iniciar","detalle":"Dosis baja.","icono":"Pill","evidencia":"Esquema."},{"titulo":"Controlar","detalle":"Presión, potasio y TFG.","icono":"LineChart","evidencia":"Resultados."},{"titulo":"Titular","detalle":"Cada 1-2 semanas.","icono":"RefreshCw","evidencia":"Ajuste."},{"titulo":"Manejar","detalle":"Tos, angioedema o hiperpotasemia.","icono":"AlertTriangle","evidencia":"Intervención."},{"titulo":"Mantener","detalle":"Dosis objetivo tolerada.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"Tos con enalapril","contexto":"Paciente con FEVI reducida y tos seca con enalapril.","pregunta":"¿Qué hacer?","opciones":[{"texto":"Aumentar enalapril.","correcta":false,"retro":"Empeora la tos."},{"texto":"Cambiar a ARA-II y mantener el bloqueo.","correcta":true,"retro":"Se conserva el beneficio con menos tos."},{"texto":"Suspender el bloqueo.","correcta":false,"retro":"La FEVI reducida lo requiere."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$IECA y ARA-II en la IC con FEVI reducida: cuándo usarlos, dosis objetivo y efectos adversos$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$IECA y ARA-II en la IC con FEVI reducida: cuándo usarlos, dosis objetivo y efectos adversos$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
