  END IF;

  -- 10. Betabloqueadores con evidencia en IC: bisoprolol, carvedilol, metoprolol succinato y nebivolol
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"No cualquier betabloqueador","texto":"No todos los betabloqueadores tienen la misma evidencia en insuficiencia cardíaca. Bisoprolol, carvedilol, metoprolol succinato y nebivolol han demostrado beneficio en FEVI reducida. Usar atenolol o propranolol no es equivalente. La elección importa. El inicio debe ser gradual, con vigilancia de frecuencia, presión y síntomas, y sin suspensión brusca."},"objetivos":["Identificar los betabloqueadores con evidencia.","Aplicar inicio y titulación.","Reconocer efectos adversos y precauciones.","Elegir según comorbilidad."],"conceptos":[{"icono":"Activity","termino":"Bisoprolol","definicion":"Cardioselectivo con evidencia en IC."},{"icono":"Gauge","termino":"Carvedilol","definicion":"Bloqueo beta y alfa; evidencia en IC."},{"icono":"Target","termino":"Metoprolol succinato","definicion":"Formulación de liberación prolongada con evidencia."},{"icono":"AlertTriangle","termino":"Bradicardia","definicion":"Límite para titulación."}],"secciones":[{"titulo":"Evidencia","parrafos":["Bisoprolol, carvedilol, metoprolol succinato y nebivolol han demostrado reducir mortalidad o hospitalizaciones en IC con FEVI reducida. La evidencia no se extrapola a todos los betabloqueadores. La elección depende de la comorbilidad y la tolerancia.","Se inician en dosis baja cuando el paciente está estable, sin congestión aguda. La titulación se hace cada dos a cuatro semanas."]},{"titulo":"Seguridad","parrafos":["Pueden causar bradicardia, hipotensión, fatiga y broncoespasmo. Se usan con precaución en asma y bloqueo AV. No se suspenden bruscamente.","En insuficiencia cardíaca descompensada, no se inician hasta estabilizar."]},{"titulo":"Educación","parrafos":["La educación incluye tomar a la misma hora, no suspender y reportar mareo o falta de aire. La adherencia es clave.","El QF puede revisar la frecuencia y la presión en cada contacto. La educación incluye no suspender bruscamente, reportar mareo o falta de aire y mantener la adherencia. La revisión debe incluir frecuencia, presión y síntomas de congestión. La adherencia y la educación sobre efectos adversos son parte del seguimiento. La revisión periódica permite mantener la dosis tolerada."]}],"errores":[{"error":"Usar cualquier betabloqueador.","correccion":"Solo los que tienen evidencia."},{"error":"Iniciar en descompensación.","correccion":"Se estabiliza primero."},{"error":"Suspender bruscamente.","correccion":"Riesgo de rebote."}],"comprueba":[{"pregunta":"¿Cuáles tienen evidencia?","respuesta":"Bisoprolol, carvedilol, metoprolol succinato y nebivolol."},{"pregunta":"¿Cuándo se inician?","respuesta":"Cuando el paciente está estable."},{"pregunta":"¿Qué se controla?","respuesta":"Frecuencia, presión y síntomas."}],"resumen":["No todos los betabloqueadores son iguales.","Los cuatro con evidencia son la base.","Se inician estables y se titulan.","No se suspenden bruscamente."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Bisoprolol Cinfa 10 mg comprimidos EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/78905/FT_78905.html"},{"cita":"AEMPS-CIMA. Ficha técnica de Carvedilol Cinfa 25 mg comprimidos EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/68328/FT_68328.html"}],"imagenes":[{"ubicacion":"Sección de evidencia","descripcion":"Lista de betabloqueadores con evidencia y advertencia sobre los que no la tienen.","alt":"Betabloqueadores con evidencia en insuficiencia cardíaca"}],"keywords":["betabloqueadores insuficiencia cardíaca","bisoprolol ic","carvedilol ic","metoprolol succinato ic"],"mapa":{"centro":"Betabloqueadores en IC","ramas":[{"titulo":"Con evidencia","icono":"Activity","nodos":["Bisoprolol","Carvedilol","Metoprolol succinato","Nebivolol"]},{"titulo":"Inicio","icono":"CalendarClock","nodos":["Dosis baja","Estable","Titular"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Bradicardia","Hipotensión","Fatiga"]},{"titulo":"Precaución","icono":"Wind","nodos":["Asma","Bradicardia","Bloqueo"]}]},"proceso":{"titulo":"Cómo iniciar un betabloqueador","intro":"","pasos":[{"titulo":"Estabilizar","detalle":"Sin congestión aguda.","icono":"ShieldCheck","evidencia":"Evaluación."},{"titulo":"Iniciar","detalle":"Dosis baja.","icono":"Pill","evidencia":"Esquema."},{"titulo":"Titular","detalle":"Cada 2-4 semanas.","icono":"RefreshCw","evidencia":"Ajuste."},{"titulo":"Controlar","detalle":"Frecuencia, presión y síntomas.","icono":"LineChart","evidencia":"Resultados."},{"titulo":"Mantener","detalle":"Dosis tolerada.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"Atenolol en IC","contexto":"Paciente con FEVI reducida y atenolol.","pregunta":"¿Qué hacer?","opciones":[{"texto":"Mantener atenolol.","correcta":false,"retro":"No tiene la misma evidencia en IC."},{"texto":"Cambiar a bisoprolol, carvedilol o metoprolol succinato.","correcta":true,"retro":"Se elige un betabloqueador con evidencia."},{"texto":"Suspender sin alternativa.","correcta":false,"retro":"El beta tiene beneficio."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Betabloqueadores con evidencia en IC: bisoprolol, carvedilol, metoprolol succinato y nebivolol$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Betabloqueadores con evidencia en IC: bisoprolol, carvedilol, metoprolol succinato y nebivolol$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  IF v_n > 0 THEN
    INSERT INTO aula_republicaciones_aprobadas (course_id, aprobado_por, nota)
    SELECT v_curso, 'Dirección académica de Edvanta', 'Clases ampliadas con experiencia interactiva (133_experiencias_farmacoterapia_ic_1.sql).'
     WHERE EXISTS (SELECT 1 FROM aula_courses WHERE id = v_curso AND current_version_id IS NOT NULL);
  END IF;

  RAISE NOTICE 'Experiencias de %: % clases.', $t$Curso de Farmacoterapia de la Insuficiencia Cardíaca$t$, v_n;
END $exp$;
